package com.supercubegame.pockettodo;

import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.function.Consumer;

/** Isolated, random database names, app-private random cache roots, and synthetic media only. */
final class WholeRestoreChecks {
    static final long CAP=8L*1024*1024;interface Op{void go()throws Exception;}static void test(boolean b,String label){if(!b)throw new AssertionError(label);}static void refuse(Op o,String label)throws Exception{try{o.go();}catch(IOException|IllegalStateException|IllegalArgumentException|android.database.sqlite.SQLiteConstraintException ok){return;}throw new AssertionError("ACCEPTED_"+label);}
    static void refuseFor(Op op,String marker)throws Exception{try{op.go();}catch(IOException|IllegalStateException|IllegalArgumentException|android.database.sqlite.SQLiteConstraintException e){for(Throwable t=e;t!=null;t=t.getCause())if(String.valueOf(t.getMessage()).contains(marker))return;throw new AssertionError("wrong refusal, expected: "+marker,e);}throw new AssertionError("accepted: "+marker);}
    static AppDatabase open(Context c,String name,int v,boolean fresh)throws Exception{Path p=c.getDatabasePath(name).toPath();if(fresh){Files.createDirectories(p.getParent());try(DirectoryStream<Path> s=Files.newDirectoryStream(p.getParent(),name+"-*")){test(!s.iterator().hasNext(),"existing sidecars");}Files.createFile(p);}return v==4?AppDatabase.openSchema4(c,name):v==3?AppDatabase.openSchema3(c,name):new AppDatabase(c,name);}
    static final String[] TABLES={"revision","categories","applications","activities","paths","tags","batches","ledger","checkins","media","notes","blocks","fields","field_options","field_values","field_notes","todos","legacy_imports","category_shortcuts"};
    static byte[] cells(SQLiteDatabase d)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream o=new DataOutputStream(bytes);d.beginTransactionNonExclusive();try{int version=d.getVersion();o.writeInt(version);for(String t:TABLES){boolean links=t.equals("category_shortcuts");if(links&&version<4)continue;o.writeUTF(t);try(Cursor c=d.rawQuery(links?"SELECT * FROM category_shortcuts ORDER BY category_id,application_id":"SELECT rowid,* FROM "+t+" ORDER BY rowid",null)){o.writeInt(c.getCount());while(c.moveToNext())for(int i=0;i<c.getColumnCount();i++){int ty=c.getType(i);o.writeByte(ty);if(ty==1)o.writeLong(c.getLong(i));else if(ty==3)o.writeUTF(c.getString(i));else if(ty==4){byte[] b=c.getBlob(i);o.writeInt(b.length);o.write(b);}else test(ty==0,"invalid cell type");}}}d.setTransactionSuccessful();return bytes.toByteArray();}finally{d.endTransaction();}}
    static void fill(AppDatabase d,String key,int v,MediaRepository media)throws Exception{d.addCategory(1,"同名");d.addApplication(2,"应用","");d.addActivity(3,1,2,"重复标题");d.addActivity(4,1,2,"重复标题");d.addTodo(key,"同名待办");d.addTodo(key+"-sibling","同名待办");d.savePath(3,Arrays.asList(key,"乙"));d.saveTags(4,Arrays.asList("一","二"));long cents=key.equals("before")?321:759;d.recordBatch(key+"-batch",Collections.singletonList(new Ledger.Entry(key+"-entry",3,LocalDate.parse("2024-02-29"),Ledger.Kind.EXPENSE,cents,key)));d.putMark(new CalendarRules.Mark(4,LocalDate.parse("2024-02-29"),CalendarRules.Status.DONE,key,Instant.EPOCH));String same=media.copy(new ByteArrayInputStream(new byte[]{0,2,5}));byte[] bytes=key.getBytes(StandardCharsets.UTF_8);String original=media.copy(new ByteArrayInputStream(bytes));d.registerMedia(same,"image/png",3);d.registerMedia(original,"image/jpeg",bytes.length);d.createNote(key+"-note",4,"私有");d.saveNote(key+"-note",Collections.singletonList(NoteDocument.Block.image(key+"-image",same,"图",true)));if(v>=3)d.getWritableDatabase().execSQL("UPDATE blocks SET original_asset_id=? WHERE id=?",new Object[]{original,key+"-image"});if(v==4&&key.equals("before"))d.setShortcut(1,2,true);d.getWritableDatabase().execSQL("UPDATE todos SET rowid=25 WHERE id=?",new Object[]{key+"-sibling"});d.getWritableDatabase().execSQL("UPDATE notes SET rowid=17 WHERE id=?",new Object[]{key+"-note"});}
    static AppDatabase.RestoreUndo forward(AppDatabase d,Path zip,Path stage,MediaRepository media)throws Exception{try(AppDatabase.RestorePlan p=d.prepareRestore(zip,stage,CAP)){return d.confirmRestoreWithUndo(p,media);}}
    static void run(Context c,int v,Consumer<String> mark)throws Exception{String prefix="whole-"+UUID.randomUUID(),db=prefix+".db",src=prefix+"-in.db";Path r=Files.createTempDirectory(c.getCacheDir().toPath(),"whole-check-"),zip=r.resolve("source.zip"),stage=r.resolve("stage"),mediaPath=r.resolve("live-media");MediaRepository m=new MediaRepository(mediaPath,CAP),other=new MediaRepository(r.resolve("input-media"),CAP);byte[] sourceState,base,raw,zipBytes;AppDatabase.RestoreUndo closed;
        try(AppDatabase source=open(c,src,v,true)){fill(source,"incoming",v,other);sourceState=source.exportState();source.exportBackup(zip,other);}zipBytes=Files.readAllBytes(zip);String oldId=MediaRepository.digest("before".getBytes(StandardCharsets.UTF_8)),newId=MediaRepository.digest("incoming".getBytes(StandardCharsets.UTF_8)),both=MediaRepository.digest(new byte[]{0,2,5});
        try(AppDatabase d=open(c,db,v,true)){fill(d,"before",v,m);base=d.exportState();raw=cells(d.getReadableDatabase());try(AppDatabase.RestorePlan p=d.prepareRestore(zip,stage,CAP)){test(!Files.exists(mediaPath.resolve(newId)),"preview published image");}test(Arrays.equals(base,d.exportState())&&Arrays.equals(raw,cells(d.getReadableDatabase())),"preview wrote");
            // A nested transaction cannot promise an actual completed commit. No published blob or reusable confirmation.
            try(AppDatabase.RestorePlan p=d.prepareRestore(zip,stage,CAP)){SQLiteDatabase outer=d.getWritableDatabase();outer.beginTransaction();try{refuseFor(()->d.confirmRestoreWithUndo(p,m),"请先结束当前事务");}finally{outer.endTransaction();}refuseFor(()->d.confirmRestoreWithUndo(p,m),"恢复预览已失效");}
            try(AppDatabase.RestorePlan p=d.prepareRestore(zip,stage,CAP)){refuseFor(()->d.confirmRestoreWithUndo(p,null),"缺少恢复媒体仓库");refuseFor(()->d.confirmRestoreWithUndo(p,m),"恢复预览已失效");}
            test(Arrays.equals(raw,cells(d.getReadableDatabase()))&&Arrays.equals(base,d.exportState())&&Files.notExists(mediaPath.resolve(newId))&&Arrays.equals(zipBytes,Files.readAllBytes(zip)),"rejected forward published data");mark.accept("owned_outer_transaction_and_missing_media_refused_v"+v);
            AppDatabase.RestoreUndo first=forward(d,zip,stage,m);test(first.previousCounts.get("todos")==2L&&first.restoredCounts.get("todos")==2L&&Arrays.equals(sourceState,d.exportState()),"forward actual incoming");try(AppDatabase foreign=open(c,db,v,false)){refuse(()->foreign.undoRestore(first),"wrong_helper");}d.undoRestore(first);refuse(()->d.undoRestore(first),"duplicate");test(Arrays.equals(raw,cells(d.getReadableDatabase()))&&Arrays.equals(base,d.exportState()),"all_before_including_rowids");for(String id:new String[]{oldId,newId,both})m.verify(id);mark.accept("whole_restore_exact_v"+v);
            // A no-revision mutation must be retained, not overwritten by an old user action.
            AppDatabase.RestoreUndo stale=forward(d,zip,stage,m);SQLiteDatabase sql=d.getWritableDatabase();sql.execSQL("UPDATE todos SET title='new input' WHERE id=?",new Object[]{"incoming"});byte[] changed=cells(sql);refuse(()->d.undoRestore(stale),"unversioned_new_data");test(Arrays.equals(changed,cells(sql)),"overwrote_post_restore_edit");refuse(()->d.undoRestore(stale),"failed_attempt_reused");
            AppDatabase.RestoreUndo same=forward(d,zip,stage,m);sql.execSQL("UPDATE todos SET title='temp' WHERE id='incoming'");sql.execSQL("UPDATE todos SET title='同名待办' WHERE id='incoming'");refuseFor(()->d.undoRestore(same),"恢复后数据已变");AppDatabase.RestoreUndo external=forward(d,zip,stage,m);try(AppDatabase second=open(c,db,v,false)){second.getWritableDatabase().execSQL("UPDATE todos SET title='outside' WHERE id='incoming'");second.getWritableDatabase().execSQL("UPDATE todos SET title='同名待办' WHERE id='incoming'");}refuseFor(()->d.undoRestore(external),"恢复后数据已变");mark.accept("same_revision_and_external_write_refused_v"+v);
            // Late failure mutates inside the same transaction: no partial row survives.
            AppDatabase.RestoreUndo late=forward(d,zip,stage,m);byte[] current=cells(sql);sql.execSQL("CREATE TEMP TRIGGER ci_restore_undo_late BEFORE INSERT ON todos BEGIN SELECT RAISE(ABORT,'undo_late'); END");try{refuseFor(()->d.undoRestore(late),"undo_late");}finally{sql.execSQL("DROP TRIGGER ci_restore_undo_late");}test(Arrays.equals(current,cells(sql)),"late_rollback");
            AppDatabase.RestoreUndo readback=forward(d,zip,stage,m);current=cells(sql);sql.execSQL("CREATE TEMP TRIGGER ci_restore_undo_shift AFTER INSERT ON todos BEGIN UPDATE todos SET title='wrong' WHERE id=NEW.id; END");try{refuseFor(()->d.undoRestore(readback),"撤销读回不一致");}finally{sql.execSQL("DROP TRIGGER ci_restore_undo_shift");}test(Arrays.equals(current,cells(sql)),"readback_rollback");mark.accept("late_failures_preserve_whole_database_v"+v);
            closed=forward(d,zip,stage,m);
        }try(AppDatabase again=open(c,db,v,false)){refuse(()->again.undoRestore(closed),"restart");test(Arrays.equals(sourceState,again.exportState())&&Arrays.equals(zipBytes,Files.readAllBytes(zip)),"persistent_forward_and_source");}
        // A lost or replaced required before-image invalidates undo; never repair/delete shared bytes.
        try(AppDatabase d=open(c,prefix+"-media.db",v,true)){MediaRepository owned=new MediaRepository(r.resolve("fault-media"),CAP);fill(d,"before",v,owned);AppDatabase.RestoreUndo u=forward(d,zip,stage,owned);byte[] committed=cells(d.getReadableDatabase());Path path=owned.path(oldId);Files.write(path,new byte[]{9,9,9,9,9,9},StandardOpenOption.TRUNCATE_EXISTING);refuseFor(()->d.undoRestore(u),"撤销所需媒体");test(Arrays.equals(committed,cells(d.getReadableDatabase())),"bad_media_partial_change");owned.verify(newId);owned.verify(both);}
        try(AppDatabase d=open(c,prefix+"-before-media.db",v,true)){MediaRepository owned=new MediaRepository(r.resolve("original-only-fault"),CAP);fill(d,"before",v,owned);byte[] prior=cells(d.getReadableDatabase());try(AppDatabase.RestorePlan p=d.prepareRestore(zip,stage,CAP)){Files.write(owned.path(oldId),new byte[]{4,3,2,1,9,8},StandardOpenOption.TRUNCATE_EXISTING);refuseFor(()->d.confirmRestoreWithUndo(p,owned),"撤销所需媒体");}test(Arrays.equals(prior,cells(d.getReadableDatabase())),"bad prior file allowed replacement");}
        mark.accept("changed_media_and_reopen_do_not_revive_v"+v);
    }
}
